  emailNotifications: EmailNotification[];
}

export interface ProfileErrors {
  name?: string;
  email?: string;
}

export const AVATAR_ACCEPT = ['image/png', 'image/jpeg', 'image/webp', 'image/gif'];
export const AVATAR_MAX_BYTES = 2 * 1024 * 1024;

