rm -rf dist && mkdir -p .verify && cat > .verify/check.tsx <<'EOF'
import { renderToStaticMarkup } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { validateProfile, initialsOf, type ProfileSettings } from '../src/profile/model';
import { ProfileSettingsForm } from '../src/profile/ProfileSettingsForm';

const base: ProfileSettings = { name: 'Анна Смирнова', email: 'a@b.ru', avatarUrl: null, language: 'ru', timezone: 'Europe/Moscow', twoFactorEnabled: false, emailNotifications: ['systemAlerts'] };
const cases: [string, Partial<ProfileSettings>, object][] = [
  ['ok', {}, {}],
  ['empty name+email', { name: '   ', email: '' }, { name: 'Укажите имя', email: 'Укажите email' }],
  ['bad email', { email: 'foo@bar' }, { email: 'Некорректный email' }],
  ['long name', { name: 'x'.repeat(65) }, { name: 'Не длиннее 64 символов' }],
];
let ok = true;
for (const [label, patch, expected] of cases) {
  const got = validateProfile({ ...base, ...patch });
  const pass = JSON.stringify(got) === JSON.stringify(expected);
  ok &&= pass;
  console.log(pass ? 'PASS' : 'FAIL', label, JSON.stringify(got));
}
console.log(initialsOf('Анна Смирнова') === 'АС' ? 'PASS' : 'FAIL', 'initials', initialsOf('Анна Смирнова'), initialsOf('  '));
const html = renderToStaticMarkup(
  <ThemeProvider theme="light">
    <ProfileSettingsForm initialValues={base} onSave={async () => {}} />
  </ThemeProvider>,
);
const checks = {
  heading: html.includes('Настройки профиля'),
  labels: ['Имя', 'Email', 'Язык интерфейса', 'Часовой пояс', 'Двухфакторная аутентификация', 'Email-уведомления', 'Новости продукта', 'Системные алерты', 'Дайджест за неделю'].every((t) => html.includes(t)),
  buttons: html.includes('Сохранить') && html.includes('Отмена'),
  saveDisabledInitially: /disabled=""[^>]*>[\s\S]*?Сохранить|Сохранить/.test(html),
  fileInput: html.includes('type="file"'),
  ids: ['profile-name', 'profile-email', 'profile-language', 'profile-timezone'].every((id) => html.includes(`id="${id}"`)),
};
console.log(checks);
console.log('SSR length', html.length);
console.log(ok ? 'ALL LOGIC PASS' : 'LOGIC FAIL');
EOF
npx vite-node .verify/check.tsx 2>&1 | grep -v "npm warn" | head -60

